     1→# ABOUTME: Global Value Numbering optimization pass for Sea of Nodes IR
     2→# ABOUTME: Implements GVN for common subexpression elimination and redundant computation removal
     3→
     4→use 5.42.0;
     5→use experimental qw(class builtin keyword_any keyword_all);
     6→use utf8;
     7→
     8→class Chalk::IR::Optimizer::GVN {
     9→    use Chalk::IR::Node;
    10→    use Chalk::IR::Graph;
    11→
    12→    # Run Global Value Numbering optimization pass
    13→    # Returns: { graph => optimized_graph, metrics => { nodes_eliminated => N, redirections => {...} } }
    14→    sub run_gvn($class, $graph) {
    15→        # Value number tracking: value_number => canonical_node_id
    16→        my $value_to_node = {};
    17→
    18→        # Node to value number mapping: node_id => value_number
    19→        my $node_to_value = {};
    20→
    21→        # Redirection map: duplicate_node_id => canonical_node_id
    22→        my $redirections = {};
    23→
    24→        # Get all nodes in a consistent order (we'll process them by ID order)
    25→        my @node_ids = sort keys %{$graph->nodes};
    26→
    27→        # Phase 1: Compute value numbers for all nodes
    28→        for my $node_id (@node_ids) {
    29→            my $node = $graph->get_node($node_id);
    30→            next unless defined($node);
    31→
    32→            # Compute value number for this node
    33→            my $value_num = $class->_compute_value_number($node, $node_to_value, $graph);
    34→
    35→            # Check if we've seen this value number before
    36→            if (exists($value_to_node->{$value_num})) {
    37→                # Found a duplicate! Record the redirection
    38→                my $canonical_id = $value_to_node->{$value_num};
    39→                $redirections->{$node_id} = $canonical_id;
    40→                # Use the canonical node's value number for this node too
    41→                $node_to_value->{$node_id} = $value_num;
    42→            } else {
    43→                # First time seeing this value - this is the canonical node
    44→                $value_to_node->{$value_num} = $node_id;
    45→                $node_to_value->{$node_id} = $value_num;
    46→            }
    47→        }
    48→
    49→        # Phase 2: Build new graph with redirections applied
    50→        my $new_graph = Chalk::IR::Graph->new();
    51→
    52→        # Track which nodes have been copied to new graph
    53→        my %copied;
    54→
    55→        # Copy nodes that aren't redirected, applying redirections to inputs
    56→        for my $node_id (@node_ids) {
    57→            # Skip nodes that are being redirected away
    58→            next if exists($redirections->{$node_id});
    59→
    60→            my $old_node = $graph->get_node($node_id);
    61→            next unless defined($old_node);
    62→
    63→            # Apply redirections to input list
    64→            my @new_inputs;
    65→            for my $input_id ($old_node->inputs->@*) {
    66→                if (defined($input_id)) {
    67→                    # Follow redirection chain if this input was redirected
    68→                    my $final_id = $class->_follow_redirections($input_id, $redirections);
    69→                    push @new_inputs, $final_id;
    70→                } else {
    71→                    push @new_inputs, undef;
    72→                }
    73→            }
    74→
    75→            # Apply redirections to attributes (if they contain node references)
    76→            my $new_attributes = $class->_redirect_attributes(
    77→                $old_node->attributes,
    78→                $redirections
    79→            );
    80→
    81→            # Create new node with redirected inputs
    82→            my $new_node = Chalk::IR::Node->new(
    83→                id         => $node_id,
    84→                op         => $old_node->op,
    85→                inputs     => \@new_inputs,
    86→                attributes => $new_attributes,
    87→            );
    88→
    89→            $new_graph->add_node($new_node);
    90→            $copied{$node_id} = 1;
    91→        }
    92→
    93→        # Preserve entry point (following any redirection)
    94→        if (defined($graph->entry)) {
    95→            my $new_entry = $class->_follow_redirections($graph->entry, $redirections);
    96→            $new_graph->set_entry($new_entry);
    97→        }
    98→
    99→        # Compute metrics
   100→        my $nodes_eliminated = scalar keys %{$redirections};
   101→
   102→        return {
   103→            graph => $new_graph,
   104→            metrics => {
   105→                nodes_eliminated => $nodes_eliminated,
   106→                redirections => $redirections,
   107→            }
   108→        };
   109→    }
   110→
   111→    # Compute value number for a node
   112→    # Returns a string that uniquely identifies the value computed by this node
   113→    sub _compute_value_number($class, $node, $node_to_value, $graph) {
   114→        my $op = $node->op;
   115→        my $attrs = $node->attributes;
   116→
   117→        # Special case: Constants
   118→        if ($op eq 'Constant') {
   119→            my $value = $attrs->{value} // '';
   120→            my $type = $attrs->{type} // '';
   121→            return "Constant:$value:$type";
   122→        }
   123→
   124→        # Special case: Proj nodes (include index)
   125→        if ($op eq 'Proj') {
   126→            my $index = $attrs->{index} // '';
   127→            # Get value number of input node
   128→            my @input_vns;
   129→            for my $input_id ($node->inputs->@*) {
   130→                if (defined($input_id) && exists($node_to_value->{$input_id})) {
   131→                    push @input_vns, $node_to_value->{$input_id};
   132→                } else {
   133→                    push @input_vns, $input_id // 'undef';
   134→                }
   135→            }
   136→            my $inputs_str = join(',', @input_vns);
   137→            return "Proj:$index:$inputs_str";
   138→        }
   139→
   140→        # Special case: Phi nodes - use identity-based comparison
   141→        # Only merge if ALL inputs are identical
   142→        if ($op eq 'Phi') {
   143→            # For Phi nodes, we use the actual input IDs rather than value numbers
   144→            # This is conservative but correct
   145→            my $inputs_str = join(',', map { $_ // 'undef' } $node->inputs->@*);
   146→            my $region_id = $attrs->{region_id} // '';
   147→            return "Phi:$region_id:$inputs_str";
   148→        }
   149→
   150→        # General case: Operations
   151→        # Get value numbers of inputs
   152→        my @input_vns;
   153→        for my $input_id ($node->inputs->@*) {
   154→            if (defined($input_id) && exists($node_to_value->{$input_id})) {
   155→                push @input_vns, $node_to_value->{$input_id};
   156→            } else {
   157→                push @input_vns, $input_id // 'undef';
   158→            }
   159→        }
   160→
   161→        # Handle commutativity for Add and Multiply
   162→        if ($op eq 'Add' || $op eq 'Multiply') {
   163→            @input_vns = sort @input_vns;
   164→        }
   165→
   166→        my $inputs_str = join(',', @input_vns);
   167→        return "$op:$inputs_str";
   168→    }
   169→
   170→    # Follow a chain of redirections to find the final canonical node
   171→    sub _follow_redirections($class, $node_id, $redirections) {
   172→        my $current = $node_id;
   173→        my %seen;
   174→
   175→        while (exists($redirections->{$current})) {
   176→            # Detect cycles (shouldn't happen, but be safe)
   177→            return $node_id if exists($seen{$current});
   178→            $seen{$current} = 1;
   179→
   180→            $current = $redirections->{$current};
   181→        }
   182→
   183→        return $current;
   184→    }
   185→
   186→    # Apply redirections to node attributes (which may contain node references)
   187→    sub _redirect_attributes($class, $attrs, $redirections) {
   188→        return {} unless defined($attrs);
   189→
   190→        my %new_attrs;
   191→
   192→        for my $key (keys( $attrs->%* )) {
   193→            my $value = $attrs->{$key};
   194→
   195→            # If this is a hash ref, it might be a NodeRef
   196→            if (ref($value) eq 'HASH') {
   197→                # Check if it's a NodeRef
   198→                if (exists($value->{op}) && $value->{op} eq 'NodeRef') {
   199→                    my $node_id = $value->{node_id};
   200→                    if (defined($node_id) && exists($redirections->{$node_id})) {
   201→                        # Redirect the NodeRef
   202→                        $new_attrs{$key} = {
   203→                            $value->%*,
   204→                            node_id => $redirections->{$node_id}
   205→                        };
   206→                    } else {
   207→                        $new_attrs{$key} = $value;
   208→                    }
   209→                } else {
   210→                    # Just copy the hash as-is
   211→                    $new_attrs{$key} = $value;
   212→                }
   213→            }
   214→            # Special case: store_id attribute (used in Load nodes)
   215→            elsif ($key eq 'store_id' && defined($value) && exists($redirections->{$value})) {
   216→                $new_attrs{$key} = $redirections->{$value};
   217→            }
   218→            # Special case: region_id attribute (used in Phi nodes)
   219→            elsif ($key eq 'region_id' && defined($value) && exists($redirections->{$value})) {
   220→                $new_attrs{$key} = $redirections->{$value};
   221→            }
   222→            else {
   223→                # Copy as-is for other types
   224→                $new_attrs{$key} = $value;
   225→            }
   226→        }
   227→
   228→        return \%new_attrs;
   229→    }
   230→}
   231→
   232→1;
   233→

