    38→                my $canonical_id = $value_to_node->{$value_num};
    39→                $redirections->{$node_id} = $canonical_id;
    40→                # Use the canonical node's value number for this node too
    41→                $node_to_value->{$node_id} = $value_num;
    42→            } else {
    43→                # First time seeing this value - this is the canonical node
    44→                $value_to_node->{$value_num} = $node_id;
    45→                $node_to_value->{$node_id} = $value_num;
    46→            }
    47→        }
