   537→    # Class and object support nodes (Issue #98 Phase 1)
   538→
   539→    method build_classdef_node($class_name, $fields) {
   540→        # Create ClassDef node for class definition
   541→        my $attributes = {
   542→            name => $class_name,
   543→            fields => $fields,
   544→        };
   545→        my $node_id = $self->next_node_id();
   546→        my $classdef = Chalk::IR::Node->new(
   547→            id            => $node_id,
   548→            op            => 'ClassDef',
   549→            inputs        => [$current_control],
   550→            attributes    => $attributes,
   551→        );
   552→        $graph->add_node($classdef);
   553→        return $classdef;
   554→    }
   555→
   556→    method build_new_node($class_name, $field_values_hash) {
   557→        # Create New node for object instantiation
   558→        # $field_values_hash is a hashref mapping field names to node objects
   559→        my @input_nodes = ($current_control);
   560→        my %field_value_refs;
   561→
   562→        # Build field references from hash
   563→        for my $field_name (sort( keys( $field_values_hash->%* ) )) {
   564→            my $value_node = $field_values_hash->{$field_name};
   565→            push @input_nodes, $value_node->id;
   566→            $field_value_refs{$field_name} = {
   567→                op => 'NodeRef',
   568→                node_id => $value_node->id
   569→            };
   570→        }
   571→
   572→        my $attributes = {
   573→            class => $class_name,
   574→            field_values => \%field_value_refs
   575→        };
   576→        my $node_id = $self->next_node_id();
   577→        my $new_obj = Chalk::IR::Node->new(
   578→            id            => $node_id,
   579→            op            => 'New',
   580→            inputs        => \@input_nodes,
   581→            attributes    => $attributes,
   582→        );
   583→        $graph->add_node($new_obj);
   584→        return $new_obj;
   585→    }
