        my $node_id = $self->next_node_id();
        my $proj = Chalk::IR::Node::Proj->new(
            id            => $node_id,
            inputs        => [$source_node->id],
            index         => $index,
            label         => $label,
        );
        $graph->add_node($proj);
        return $proj;
    }

