     1→# ABOUTME: Validator for Sea of Nodes IR graphs checking SSA properties, CFG structure, dominance, and phi nodes
     2→# ABOUTME: Provides comprehensive validation infrastructure to catch IR construction errors before compilation
     3→use 5.42.0;
     4→use experimental qw(class builtin keyword_any keyword_all);
     5→use utf8;
     6→
     7→class Chalk::IR::Validator {
     8→    use Chalk::IR::Node;
     9→    use Chalk::IR::Graph;
    10→
    11→    # Main validation entry point - runs all validators
    12→    method validate_all($graph) {
    13→        my @all_errors = ();
    14→
    15→        # Run each validator and collect errors
    16→        push @all_errors, $self->validate_cfg($graph);
    17→        push @all_errors, $self->validate_single_assignment($graph);
    18→        push @all_errors, $self->validate_dominance($graph);
    19→        push @all_errors, $self->validate_phi_placement($graph);
    20→        push @all_errors, $self->validate_loop_structure($graph);
    21→        push @all_errors, $self->validate_class_nodes($graph);
    22→        push @all_errors, $self->validate_array_nodes($graph);
    23→        push @all_errors, $self->validate_hash_nodes($graph);
    24→        push @all_errors, $self->validate_string_nodes($graph);
    25→        push @all_errors, $self->validate_module_nodes($graph);
    26→
    27→        my $success = scalar( @all_errors ) == 0 ? 1 : 0;
    28→        return ($success, \@all_errors);
    29→    }
    30→
    31→    # Validate Control Flow Graph structure
    32→    method validate_cfg($graph) {
    33→        my @errors = ();
    34→
    35→        # Check: Single Start node exists
    36→        my $start_count = 0;
    37→        my $start_id = undef;
    38→        my $nodes = $graph->nodes;
    39→
    40→        for my $node_id (keys( $nodes->%* )) {
    41→            my $node = $nodes->{$node_id};
    42→            if ($node->op eq 'Start') {
    43→                $start_count++;
    44→                $start_id = $node_id;
    45→            }
    46→        }
    47→
    48→        if ($start_count == 0) {
    49→            push @errors, "CFG validation failed: No Start node found in graph";
    50→        }
    51→        elsif ($start_count > 1) {
    52→            push @errors, "CFG validation failed: Multiple Start nodes found ($start_count), expected exactly 1";
    53→        }
    54→
    55→        # Check: At least one Return node exists
    56→        my $return_count = 0;
    57→        for my $node_id (keys( $nodes->%* )) {
    58→            my $node = $nodes->{$node_id};
    59→            if ($node->op eq 'Return') {
    60→                $return_count++;
    61→            }
    62→        }
    63→
    64→        if ($return_count == 0) {
    65→            push @errors, "CFG validation failed: No Return node found in graph";
    66→        }
    67→
    68→        # Check: All nodes reachable from Start (BFS traversal)
    69→        if (defined($start_id)) {
    70→            # Build successor map once for O(n+e) BFS instead of O(n²)
    71→            # In Sea of Nodes, inputs point TO this node FROM others,
    72→            # so we need to reverse the edges to get successors
    73→            my %successors = ();
    74→            for my $node_id (keys( $nodes->%* )) {
    75→                $successors{$node_id} = [];
    76→            }
    77→            for my $node_id (keys( $nodes->%* )) {
    78→                my $node = $nodes->{$node_id};
    79→                for my $input_id ($node->inputs->@*) {
    80→                    if (exists($nodes->{$input_id})) {
    81→                        push $successors{$input_id}->@*, $node_id;
    82→                    }
    83→                }
    84→            }
    85→
    86→            # BFS using successor map
    87→            my %reachable = ();
    88→            my @queue = ($start_id);
    89→            $reachable{$start_id} = 1;
    90→
    91→            while (scalar( @queue ) > 0) {
    92→                my $current_id = shift @queue;
    93→
    94→                # Follow all successors (nodes that depend on current node)
    95→                for my $successor_id ($successors{$current_id}->@*) {
    96→                    next if exists($reachable{$successor_id});
    97→                    $reachable{$successor_id} = 1;
    98→                    push @queue, $successor_id;
    99→                }
   100→            }
   101→
   102→            # Report unreachable nodes (except Constants which are data-only)
   103→            for my $node_id (keys( $nodes->%* )) {
   104→                if (not(exists($reachable{$node_id}))) {
   105→                    my $node = $nodes->{$node_id};
   106→                    # Constants are data-only nodes and don't need control flow reachability
   107→                    if ($node->op ne 'Constant') {
   108→                        push @errors, "CFG validation failed: Node $node_id is not reachable from Start node";
   109→                    }
   110→                }
   111→            }
   112→        }
   113→
   114→        return @errors;
   115→    }
   116→
   117→    # Validate SSA single assignment property
   118→    method validate_single_assignment($graph) {
   119→        my @errors = ();
   120→        my %assignments = ();  # variable_name => [node_ids]
   121→
   122→        my $nodes = $graph->nodes;
   123→
   124→        # Collect all Store nodes (variable assignments)
   125→        for my $node_id (keys( $nodes->%* )) {
   126→            my $node = $nodes->{$node_id};
   127→            if ($node->op eq 'Store') {
   128→                my $var_name = $node->attributes->{variable};
   129→                if (defined($var_name)) {
   130→                    $assignments{$var_name} //= [];
   131→                    push $assignments{$var_name}->@*, $node_id;
   132→                }
   133→            }
   134→        }
   135→
   136→        # Check for multiple assignments to same variable
   137→        for my $var_name (keys( %assignments )) {
   138→            my $assign_list = $assignments{$var_name};
   139→            if (scalar( $assign_list->@* ) > 1) {
   140→                my $node_list = join(', ', $assign_list->@*);
   141→                push @errors, "SSA violation: Variable $var_name is assigned more than once (in nodes: $node_list)";
   142→            }
   143→        }
   144→
   145→        return @errors;
   146→    }
   147→
   148→    # Compute dominance tree using Cooper/Harvey/Kennedy algorithm
   149→    method compute_dominance_tree($graph) {
   150→        my $nodes = $graph->nodes;
   151→        my %dom = ();  # node_id => immediate_dominator_id
   152→
   153→        # Find Start node
   154→        my $start_id = undef;
   155→        for my $node_id (keys( $nodes->%* )) {
   156→            my $node = $nodes->{$node_id};
   157→            if ($node->op eq 'Start') {
   158→                $start_id = $node_id;
   159→                last;
   160→            }
   161→        }
   162→
   163→        return \%dom unless defined($start_id);
   164→
   165→        # Compute node depths for _intersect heuristic
   166→        my $depth_map = $self->_compute_node_depths($graph);
   167→
   168→        # Build reverse graph (predecessors)
   169→        my %preds = ();  # node_id => [predecessor_ids]
   170→        for my $node_id (keys( $nodes->%* )) {
   171→            $preds{$node_id} = [];
   172→        }
   173→
   174→        for my $node_id (keys( $nodes->%* )) {
   175→            my $node = $nodes->{$node_id};
   176→            for my $input_id ($node->inputs->@*) {
   177→                if (exists($nodes->{$input_id})) {
   178→                    push $preds{$node_id}->@*, $input_id;
   179→                }
   180→            }
   181→        }
   182→
   183→        # Initialize: Start dominates itself
   184→        $dom{$start_id} = $start_id;
   185→
   186→        # Iterative dataflow until convergence
   187→        my $changed = 1;
   188→        my $max_iterations = scalar( keys( $nodes->%* ) ) * 2;
   189→        my $iterations = 0;
   190→
   191→        while ($changed) {
   192→            if ($iterations > $max_iterations) {
   193→                last;
   194→            }
   195→            $changed = 0;
   196→            $iterations++;
   197→
   198→            for my $node_id (keys( $nodes->%* )) {
   199→                next if $node_id eq $start_id;
   200→
   201→                my @pred_list = $preds{$node_id}->@*;
   202→                next if scalar( @pred_list ) == 0;
   203→
   204→                # Find first processed predecessor
   205→                my $new_idom = undef;
   206→                for my $pred_id (@pred_list) {
   207→                    if (exists($dom{$pred_id})) {
   208→                        $new_idom = $pred_id;
   209→                        last;
   210→                    }
   211→                }
   212→
   213→                next unless defined($new_idom);
   214→
   215→                # Intersect with all other predecessors
   216→                for my $pred_id (@pred_list) {
   217→                    next if $pred_id eq $new_idom;
   218→                    next unless exists($dom{$pred_id});
   219→
   220→                    $new_idom = $self->_intersect(\%dom, $pred_id, $new_idom, $depth_map);
   221→                }
   222→
   223→                # Update if changed
   224→                if (not(exists($dom{$node_id}))) {
   225→                    $dom{$node_id} = $new_idom;
   226→                    $changed = 1;
   227→                }
   228→                elsif ($dom{$node_id} ne $new_idom) {
   229→                    $dom{$node_id} = $new_idom;
   230→                    $changed = 1;
   231→                }
   232→            }
   233→        }
   234→
   235→        return \%dom;
   236→    }
   237→
   238→    # Helper: Find intersection of two nodes in dominance tree
   239→    method _intersect($dom, $b1, $b2, $depth_map = undef) {
   240→        my $finger1 = $b1;
   241→        my $finger2 = $b2;
   242→
   243→        while ($finger1 ne $finger2) {
   244→            # Move up dominance tree
   245→            while ($self->_node_depth($finger1, $depth_map) > $self->_node_depth($finger2, $depth_map)) {
   246→                $finger1 = $dom->{$finger1};
   247→                last unless defined($finger1);
   248→            }
   249→            last unless defined($finger1);
   250→
   251→            while ($self->_node_depth($finger2, $depth_map) > $self->_node_depth($finger1, $depth_map)) {
   252→                $finger2 = $dom->{$finger2};
   253→                last unless defined($finger2);
   254→            }
   255→            last unless defined($finger2);
   256→
   257→            if ($finger1 eq $finger2) {
   258→                last;
   259→            }
   260→
   261→            # Both at same depth, move up together
   262→            $finger1 = $dom->{$finger1};
   263→            $finger2 = $dom->{$finger2};
   264→
   265→            last unless defined($finger1);
   266→            last unless defined($finger2);
   267→        }
   268→
   269→        return $finger1;
   270→    }
   271→
   272→    # Helper: Compute CFG depth for all nodes via BFS from Start
   273→    # Returns hashref mapping node_id => depth
   274→    method _compute_node_depths($graph) {
   275→        my $nodes = $graph->nodes;
   276→        my %depths = ();
   277→
   278→        # Find Start node
   279→        my $start_id = undef;
   280→        for my $node_id (keys( $nodes->%* )) {
   281→            my $node = $nodes->{$node_id};
   282→            if ($node->op eq 'Start') {
   283→                $start_id = $node_id;
   284→                last;
   285→            }
   286→        }
   287→
   288→        return \%depths unless defined($start_id);
   289→
   290→        # BFS to compute depths
   291→        my @queue = ($start_id);
   292→        $depths{$start_id} = 0;
   293→
   294→        while (scalar( @queue ) > 0) {
   295→            my $current_id = shift @queue;
   296→            my $current_depth = $depths{$current_id};
   297→
   298→            # Find all nodes that have current_id as input
   299→            for my $node_id (keys( $nodes->%* )) {
   300→                next if exists($depths{$node_id});
   301→                my $node = $nodes->{$node_id};
   302→
   303→                for my $input_id ($node->inputs->@*) {
   304→                    if ($input_id eq $current_id) {
   305→                        $depths{$node_id} = $current_depth + 1;
   306→                        push @queue, $node_id;
   307→                        last;
   308→                    }
   309→                }
   310→            }
   311→        }
   312→
   313→        return \%depths;
   314→    }
   315→
   316→    # Helper: Get node depth from cached depth map
   317→    # Falls back to parsing node_id for backward compatibility
   318→    method _node_depth($node_id, $depth_map = undef) {
   319→        return 0 unless defined($node_id);
   320→
   321→        # Use cached depth if available
   322→        if (defined($depth_map) && exists($depth_map->{$node_id})) {
   323→            return $depth_map->{$node_id};
   324→        }
   325→
   326→        # Fallback: parse node_id (e.g., "node_123" => 123)
   327→        # This is a heuristic and may not reflect true CFG depth
   328→        my $pattern = qr/node_(\d+)/;
   329→        if ($node_id =~ $pattern) {
   330→            return $1;
   331→        }
   332→        return 0;
