   335→    # Validate dominance property: definitions dominate uses
   336→    method validate_dominance($graph) {
   337→        my @errors = ();
   338→
   339→        my $dom_tree = $self->compute_dominance_tree($graph);
   340→        my $nodes = $graph->nodes;
   341→
   342→        # Check each Load node: its Store must exist and be valid
   343→        for my $node_id (keys( $nodes->%* )) {
   344→            my $node = $nodes->{$node_id};
   345→            if ($node->op eq 'Load') {
   346→                my $var_name = $node->attributes->{variable};
   347→                my $store_id = $node->attributes->{store_id};
   348→
   349→                if (defined($store_id)) {
   350→                    if (defined($var_name)) {
   351→                        # Check if store exists
   352→                        if (not(exists($nodes->{$store_id}))) {
   353→                            push @errors, "Dominance violation: Load of $var_name in $node_id references non-existent Store $store_id";
   354→                            next;
   355→                        }
   356→
   357→                        my $store_node = $nodes->{$store_id};
   358→                        if ($store_node->op ne 'Store') {
   359→                            push @errors, "Dominance violation: Load of $var_name in $node_id references $store_id which is not a Store node";
   360→                            next;
   361→                        }
   362→
   363→                        # For graphs with control flow (Region nodes), check strict dominance
   364→                        # For linear graphs (Chapters 1-4), the store_id reference is sufficient
   365→                        my $has_control_flow = $self->_has_control_flow($graph);
   366→
   367→                        if ($has_control_flow) {
   368→                            my $is_dominated = $self->_dominates($dom_tree, $store_id, $node_id);
   369→                            if (not($is_dominated)) {
   370→                                push @errors, "Dominance violation: Load of $var_name in $node_id is not dominated by its Store in $store_id";
   371→                            }
   372→                        }
   373→                    }
   374→                }
   375→            }
   376→        }
   377→
   378→        return @errors;
   379→    }
   380→
   381→    # Helper: Check if graph has control flow (Region/If nodes)
   382→    method _has_control_flow($graph) {
   383→        my $nodes = $graph->nodes;
   384→        for my $node_id (keys( $nodes->%* )) {
   385→            my $node = $nodes->{$node_id};
   386→            if ($node->op eq 'Region' || $node->op eq 'If') {
   387→                return 1;
   388→            }
   389→        }
   390→        return 0;
   391→    }
