   393→    # Helper: Check if dominator_id dominates target_id
   394→    method _dominates($dom_tree, $dominator_id, $target_id) {
   395→        return 1 if $dominator_id eq $target_id;
   396→
   397→        # Walk up dominance tree from target
   398→        my $current = $target_id;
   399→        my $max_steps = 100;
   400→        my $steps = 0;
   401→
   402→        while (defined($current)) {
   403→            if ($steps > $max_steps) {
   404→                last;
   405→            }
   406→            $steps++;
   407→
   408→            if (exists($dom_tree->{$current})) {
   409→                $current = $dom_tree->{$current};
   410→                if (defined($current)) {
   411→                    if ($current eq $dominator_id) {
   412→                        return 1;
   413→                    }
   414→                }
   415→            }
   416→            else {
   417→                last;
   418→            }
   419→        }
   420→
   421→        return 0;
   422→    }
