   424→    # Validate phi node placement (prepare for Chapter 5)
   425→    method validate_phi_placement($graph) {
   426→        my @errors = ();
   427→
   428→        my $nodes = $graph->nodes;
   429→
   430→        # Check each Phi node
   431→        for my $node_id (keys( $nodes->%* )) {
   432→            my $node = $nodes->{$node_id};
   433→            next unless $node->op eq 'Phi';
   434→
   435→            # Phi must be at a Region (control flow merge point)
   436→            my $phi_inputs = $node->inputs;
   437→            if (scalar( $phi_inputs->@* ) == 0) {
   438→                push @errors, "Phi node $node_id has no control input (must connect to Region)";
   439→                next;
   440→            }
   441→
   442→            my $region_id = $phi_inputs->[0];
   443→            if (exists($nodes->{$region_id})) {
   444→                my $region_node = $nodes->{$region_id};
   445→                if ($region_node->op ne 'Region' && $region_node->op ne 'Loop') {
   446→                    push @errors, "Phi node $node_id is not at a Region/Loop merge point (control input is " . $region_node->op . ")";
   447→                }
   448→                else {
   449→                    # Count region/loop predecessors
   450→                    my $region_preds = $region_node->inputs;
   451→                    my $expected_alternatives = scalar( $region_preds->@* );
   452→
   453→                    # Count phi alternatives from standardized inputs array
   454→                    # Phi nodes use inputs array: inputs => [ctrl, val1, val2, ...]
   455→                    # This is the standardized representation as per GitHub Issue #80
   456→                    my $phi_inputs = $node->inputs;
   457→                    my $actual_alternatives = scalar( $phi_inputs->@* ) - 1;  # Subtract control input
   458→
   459→                    if ($actual_alternatives != $expected_alternatives) {
   460→                        push @errors, "Phi node $node_id in node $region_id expects $expected_alternatives value inputs ($expected_alternatives predecessors) but has $actual_alternatives";
   461→                    }
   462→                }
   463→            }
   464→            else {
   465→                push @errors, "Phi node $node_id references non-existent Region $region_id";
   466→            }
   467→        }
   468→
   469→        return @errors;
   470→    }
