   472→    # Validate Loop node structure and semantics
   473→    method validate_loop_structure($graph) {
   474→        my @errors = ();
   475→
   476→        my $nodes = $graph->nodes;
   477→
   478→        # Check each Loop node
   479→        for my $node_id (keys( $nodes->%* )) {
   480→            my $node = $nodes->{$node_id};
   481→            next unless $node->op eq 'Loop';
   482→
   483→            # Loop must have exactly 2 inputs: entry control + backedge
   484→            my $loop_inputs = $node->inputs;
   485→            my $num_inputs = scalar( $loop_inputs->@* );
   486→
   487→            if ($num_inputs < 1) {
   488→                push @errors, "Loop node $node_id has no entry control input";
   489→            }
   490→            elsif ($num_inputs == 1) {
   491→                # Loop with only entry, no backedge - might be under construction
   492→                # This is valid during IR building (lazy phi pattern)
   493→            }
   494→            elsif ($num_inputs == 2) {
   495→                # Valid: entry + backedge
   496→            }
   497→            elsif ($num_inputs > 2) {
   498→                push @errors, "Loop node $node_id has $num_inputs inputs, expected exactly 2 (entry + backedge)";
   499→            }
   500→
   501→            # Check for unreachable loops (no exit path)
   502→            # A loop should have an If node as successor that provides exit
   503→            if ($num_inputs == 2) {
   504→                my $has_exit = $self->_loop_has_exit($graph, $node_id);
   505→                unless ($has_exit) {
   506→                    # Note: Infinite loops are valid (e.g., while(1) { ... })
   507→                    # This is informational, not an error
   508→                    # push @errors, "Loop node $node_id may be infinite (no exit condition detected)";
   509→                }
   510→            }
   511→        }
   512→
   513→        return @errors;
   514→    }
   515→
   516→    # Helper: Check if loop has an exit path (If node with false branch)
   517→    method _loop_has_exit($graph, $loop_id) {
   518→        my $nodes = $graph->nodes;
   519→
   520→        # Look for If nodes that use the loop as control
   521→        for my $node_id (keys( $nodes->%* )) {
   522→            my $node = $nodes->{$node_id};
   523→            if ($node->op eq 'If') {
   524→                my $inputs = $node->inputs;
   525→                if (scalar( $inputs->@* ) > 0 && $inputs->[0] eq $loop_id) {
   526→                    # Found If node controlled by this loop
   527→                    # If has both true and false projections - exit exists
   528→                    return 1;
   529→                }
   530→            }
   531→        }
   532→
   533→        return 0;
   534→    }
