            }

            # Validate StrLength nodes
            elsif ($op eq 'StrLength') {
                my $attrs = $node->attributes;

                # StrLength must have 'string' attribute
                if (!exists($attrs->{string})) {
                    push @errors, "StrLength node $node_id missing required 'string' attribute";
